eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   EPISODES: () => (/* binding */ EPISODES),\n/* harmony export */   PODCASTS: () => (/* binding */ PODCASTS),\n/* harmony export */   getEpisode: () => (/* binding */ getEpisode)\n/* harmony export */ });\nconst PODCASTS = {\n    label: \"IDEAS, INSIGHTS & CONVERSATIONS\",\n    heading: \"Conversations That Move Business Forward.\",\n    description: \"Expert roundtables with global recruitment innovators exploring offshore leverage, AI sourcing, and scaling strategies.\",\n    linkLabel: \"View All Episodes\"\n};\nconst EPISODES = [\n    {\n        slug: \"restructuring-recruitment-overhead\",\n        category: \"The Aakash AP Podcast • Ep 24\",\n        title: \"Restructuring Recruitment Overhead: The Shift to Hybrid Global Teams\",\n        description: \"How mid-sized UK staffing firms are maintaining 35% EBIT margins using integrated offshore desks.\",\n        duration: \"18 min listen\",\n        date: \"Broadcasted Oct 2025\",\n        image: \"/images/podcast-1.jpg\",\n        imageAlt: \"Two international recruiting leaders in a professional broadcast studio wearing headphones and speaking into broadcast microphones discussing global recruitment process outsourcing strategies.\",\n        guest: \"Alistair Crawford\",\n        guestRole: \"Managing Director, TechSearch UK\",\n        summary: \"Alistair Crawford explains how a twelve-desk UK technology agency rebuilt its cost base around a hybrid model that combines onshore consultants with offshore delivery pods. The conversation covers the board-level case for the shift, the mistakes of an early iteration, and the metrics that convinced a sceptical leadership team to commit.\",\n        takeaways: [\n            \"Hybrid desks cut delivery cost per placement by roughly a third within two quarters.\",\n            \"Offshore pods work best when they own defined stages, not scattered tasks.\",\n            \"Keep client-facing ownership onshore and move research offshore.\",\n            \"Set a 90-day review gate before committing to full pod expansion.\",\n            \"Measure hybrid success by gross margin per desk, not headcount.\"\n        ],\n        chapters: [\n            {\n                time: \"00:00\",\n                title: \"Why overhead became the board's priority\"\n            },\n            {\n                time: \"02:40\",\n                title: \"The first failed offshore attempt\"\n            },\n            {\n                time: \"05:15\",\n                title: \"Designing the hybrid desk structure\"\n            },\n            {\n                time: \"08:30\",\n                title: \"Client reaction and confidentiality concerns\"\n            },\n            {\n                time: \"12:05\",\n                title: \"Metrics that justified expansion\"\n            },\n            {\n                time: \"15:20\",\n                title: \"Advice for managing directors considering the shift\"\n            }\n        ]\n    },\n    {\n        slug: \"ats-governance-data-hygiene\",\n        category: \"Executive Masterclass\",\n        title: \"ATS Governance & Data Hygiene: Turning Dormant Pipelines into Placements\",\n        description: \"Best practices for Bullhorn and Vincere database enrichment without wasting consultant time.\",\n        duration: \"Keynote 24 min\",\n        date: \"Released Nov 2025\",\n        image: \"/images/podcast-2.jpg\",\n        imageAlt: \"A tech executive speaking on an international conference stage with widescreen presentations displaying recruitment pipeline efficiency metrics and global candidate workflow diagrams.\",\n        guest: \"Elena Vasquez\",\n        guestRole: \"Head of Delivery, Aakash AP\",\n        summary: \"Elena Vasquez presents a keynote on why most recruitment databases quietly decay and how structured governance reverses the trend. She walks through hygiene routines inside Bullhorn, Vincere, and JobAdder, then shows how dormant candidate records become live placements once ownership and cadence are clearly defined.\",\n        takeaways: [\n            \"Most ATS databases decay because no one owns record quality day to day.\",\n            \"Assign named data stewards inside existing desks rather than a new role.\",\n            \"Standardise tags and pipeline stages before any re-engagement campaign.\",\n            \"A disciplined reactivation sprint can surface placements from year-old records.\",\n            \"Measure hygiene with weekly exception reports, not annual clean-ups.\"\n        ],\n        chapters: [\n            {\n                time: \"00:00\",\n                title: \"Why dormant pipelines are a hidden asset\"\n            },\n            {\n                time: \"04:10\",\n                title: \"How databases decay: five common patterns\"\n            },\n            {\n                time: \"08:45\",\n                title: \"Designing a data steward model\"\n            },\n            {\n                time: \"13:00\",\n                title: \"Bullhorn and Vincere hygiene routines\"\n            },\n            {\n                time: \"17:30\",\n                title: \"Reactivating candidates: sequence and tone\"\n            },\n            {\n                time: \"21:15\",\n                title: \"Measuring placements from reactivated records\"\n            }\n        ]\n    },\n    {\n        slug: \"candidate-engagement-2025\",\n        category: \"The Aakash AP Podcast • Ep 25\",\n        title: \"Candidate Engagement in 2025: Why Automated Mass Messaging is Failing\",\n        description: \"Why human-led personalisation paired with offshore scale yields 4x response rates across senior executives.\",\n        duration: \"15 min listen\",\n        date: \"Broadcasted Dec 2025\",\n        image: \"/images/podcast-3.jpg\",\n        imageAlt: \"A round-table discussion between three talent acquisition leaders in a modern conference room with coffee and digital tablets discussing international hiring dynamics.\",\n        guest: \"Morgan Reynolds\",\n        guestRole: \"VP Operations, Beacon Staffing USA\",\n        summary: \"Morgan Reynolds explains why mass automation has degraded candidate response rates across US staffing markets and what replaced it at Beacon Staffing. The discussion covers human-led personalisation at offshore scale, channel mix by seniority, and the response metrics that actually predict placement outcomes.\",\n        takeaways: [\n            \"Mass sequences now compete with dozens of identical messages per candidate.\",\n            \"Human-led personalisation at volume beats automation with no context.\",\n            \"Response rates recover when offshore teams send fewer, better-researched messages.\",\n            \"Track reply quality and interview requests, not just open rates.\",\n            \"Blend SMS, email, and calls according to candidate seniority and sector.\"\n        ],\n        chapters: [\n            {\n                time: \"00:00\",\n                title: \"Why response rates collapsed across US desks\"\n            },\n            {\n                time: \"02:35\",\n                title: \"How automation damaged candidate trust\"\n            },\n            {\n                time: \"05:20\",\n                title: \"Rebuilding engagement with human-led outreach\"\n            },\n            {\n                time: \"08:10\",\n                title: \"Scaling personalisation through offshore teams\"\n            },\n            {\n                time: \"11:00\",\n                title: \"Channel mix by seniority and sector\"\n            },\n            {\n                time: \"13:25\",\n                title: \"Metrics that predict placement outcomes\"\n            }\n        ]\n    }\n];\nfunction getEpisode(slug) {\n    return EPISODES.find((episode)=>episode.slug === slug);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./data/podcasts.ts\n");

